import frappe
import datetime as py_datetime

def _my_to_datetime(val):
    if not val:
        return None
    if isinstance(val, str):
        return frappe.utils.get_datetime(val)
    return val

def _my_shift_time_to_datetime(dateval, timeval):
    if not dateval or not timeval:
        return None
    if isinstance(dateval, str):
        dateval = frappe.utils.getdate(dateval)
    if isinstance(timeval, str):
        timeval = frappe.utils.get_time(timeval)
    return py_datetime.datetime.combine(dateval, timeval)

start_date = doc.start_date
end_date = doc.end_date
employee = doc.employee
total_shortfall = 0.0

records = frappe.get_all(
    "Attendance",
    filters={
        "employee": employee,
        "attendance_date": ["between", [start_date, end_date]],
        "docstatus": 1
    },
    fields=[
        "name",
        "late_entry",
        "early_exit",
        "in_time",
        "out_time",
        "shift",
        "working_hours",
        "status",
        "attendance_date"
    ]
)

for att in records:
    shift_start, shift_end, half_day_threshold = None, None, None

    if att.shift:
        shift_doc = frappe.get_doc("Shift Type", att.shift)
        shift_start = _my_shift_time_to_datetime(att.attendance_date, getattr(shift_doc, "start_time", None))
        shift_end = _my_shift_time_to_datetime(att.attendance_date, getattr(shift_doc, "end_time", None))
        half_day_threshold = getattr(shift_doc, "working_hours_threshold_for_half_day", None)

    in_time = _my_to_datetime(att.in_time)
    out_time = _my_to_datetime(att.out_time)

    # Late Entry calculation
    if att.late_entry and in_time and shift_start:
        diff = (in_time - shift_start).total_seconds() / 3600.0
        if diff > 0:
            total_shortfall += diff

    # Early Exit calculation
    if att.early_exit and out_time and shift_end:
        diff = (shift_end - out_time).total_seconds() / 3600.0
        if diff > 0:
            total_shortfall += diff

    # Half-day calculation
    if att.status == "Half Day" and half_day_threshold and att.working_hours is not None:
        diff = half_day_threshold - att.working_hours
        if diff > 0:
            total_shortfall += diff

doc.custom_working_hours_shortfall = round(total_shortfall, 2)

# ERPNext Server Script for Payslip Working Hours Shortfall Calculation
# Script runs directly in global scope where 'doc' is available

# Check if required fields are present
if not doc.employee or not doc.start_date or not doc.end_date:
    # Exit if essential fields are missing
    pass
else:
    total_shortfall_hours = 0.0

    # Get all attendance records for the employee in the payroll period
    attendance_records = frappe.get_all(
        "Attendance",
        filters={
            "employee": doc.employee,
            "attendance_date": ["between", [doc.start_date, doc.end_date]],
            "status": ["in", ["Present", "Half Day"]],
            "docstatus": 1
        },
        fields=[
            "name", "attendance_date", "shift", "in_time", "out_time", 
            "late_entry", "early_exit", "status", "working_hours"
        ]
    )

    for attendance in attendance_records:
        attendance_shortfall = 0.0

        # Skip half days for late entry and early exit calculation
        if attendance.status != "Half Day":
            # Calculate late entry shortfall
            if attendance.late_entry and attendance.in_time and attendance.shift:
                # Get shift details
                try:
                    shift_type = frappe.get_doc("Shift Type", attendance.shift)
                    if shift_type and shift_type.start_time:
                        # Use frappe.utils functions that are available globally
                        shift_start_datetime = frappe.utils.datetime.combine(
                            frappe.utils.getdate(attendance.attendance_date), 
                            shift_type.start_time
                        )
                        actual_checkin_datetime = frappe.utils.get_datetime(attendance.in_time)

                        if actual_checkin_datetime > shift_start_datetime:
                            # Calculate time difference in hours using frappe utils
                            late_hours = frappe.utils.time_diff_in_hours(
                                actual_checkin_datetime, 
                                shift_start_datetime
                            )
                            attendance_shortfall += late_hours
                except:
                    pass

            # Calculate early exit shortfall
            if attendance.early_exit and attendance.out_time and attendance.shift:
                # Get shift details
                try:
                    shift_type = frappe.get_doc("Shift Type", attendance.shift)
                    if shift_type and shift_type.end_time:
                        # Use frappe.utils functions that are available globally
                        shift_end_datetime = frappe.utils.datetime.combine(
                            frappe.utils.getdate(attendance.attendance_date), 
                            shift_type.end_time
                        )
                        actual_checkout_datetime = frappe.utils.get_datetime(attendance.out_time)

                        if actual_checkout_datetime < shift_end_datetime:
                            # Calculate time difference in hours using frappe utils
                            early_hours = frappe.utils.time_diff_in_hours(
                                shift_end_datetime, 
                                actual_checkout_datetime
                            )
                            attendance_shortfall += early_hours
                except:
                    pass

        # Calculate half day shortfall
        elif attendance.status == "Half Day" and attendance.working_hours and attendance.shift:
            try:
                shift_type = frappe.get_doc("Shift Type", attendance.shift)
                if shift_type and hasattr(shift_type, 'working_hours_threshold_for_half_day') and shift_type.working_hours_threshold_for_half_day:
                    threshold_hours = frappe.utils.flt(shift_type.working_hours_threshold_for_half_day)
                    actual_hours = frappe.utils.flt(attendance.working_hours)

                    if threshold_hours > actual_hours:
                        half_day_shortfall = threshold_hours - actual_hours
                        attendance_shortfall += half_day_shortfall
            except:
                pass

        total_shortfall_hours += attendance_shortfall

    # Set the shortfall hours in the custom field (round to 2 decimal places)
    doc.custom_working_hours_shortfall = frappe.utils.flt(total_shortfall_hours, 2)
